import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.VvOSaRrC.js";const i="/kroot-docs/assets/img-01.DFd2NQ8J.png",r="/kroot-docs/assets/img-02.CuZ_f-bN.png",c="/kroot-docs/assets/img-03.KCymS19U.png",l="/kroot-docs/assets/img-04.Bu6ullSg.png",d="/kroot-docs/assets/img-05.C1gfLvfq.png",n="/kroot-docs/assets/img-06.E6Md-2Z4.png",h="/kroot-docs/assets/img-07.lrsUfqkj.png",p="/kroot-docs/assets/img-08.BPmDFmmr.png",m="/kroot-docs/assets/img-09.Bp39Sqf8.png",g="/kroot-docs/assets/img-10.BUqhOgtd.png",_="/kroot-docs/assets/img-11.CM5e-WQ5.png",u="/kroot-docs/assets/img-12.C6zptAJ9.png",b="/kroot-docs/assets/img-13.Dmm1kcZ0.png",k="/kroot-docs/assets/img-14.DUYbD7EK.png",f="/kroot-docs/assets/img-15.BilmN_0I.png",q="/kroot-docs/assets/img-16.AzVN4tIl.png",x="/kroot-docs/assets/img-17.DaCMX-7d.png",y=JSON.parse('{"title":"Git Bash 설치 가이드 (Windows)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/git-bash-install.md","filePath":"guides/git-bash-install.md"}'),P={name:"guides/git-bash-install.md"};function G(B,e,C,N,S,T){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="git-bash-설치-가이드-windows" tabindex="-1">Git Bash 설치 가이드 (Windows) <a class="header-anchor" href="#git-bash-설치-가이드-windows" aria-label="Permalink to &quot;Git Bash 설치 가이드 (Windows)&quot;">​</a></h1><p>Git Bash는 Windows에서 <code>git</code>, <code>ls</code>, <code>cd</code>, <code>mkdir</code> 같은 명령을 편하게 사용할 수 있게 해 주는 터미널 환경이다. 이 책의 실습은 Windows에서 Git Bash 기준으로 진행한다.</p><blockquote><p>Mac 사용자는 Git이 기본 제공되거나 처음 실행 시 개발자 도구 설치 안내가 나오므로, 이 문서를 따로 따라 할 필요가 없다. 터미널에서 <code>git --version</code>으로 확인만 하면 된다.</p></blockquote><ul><li>공식 다운로드: <a href="https://git-scm.com" target="_blank" rel="noreferrer">https://git-scm.com</a></li><li>본 가이드 출처(설치 화면): <a href="https://xangmin.tistory.com/102" target="_blank" rel="noreferrer">https://xangmin.tistory.com/102</a></li></ul><hr><h2 id="_1-설치-파일-다운로드" tabindex="-1">1. 설치 파일 다운로드 <a class="header-anchor" href="#_1-설치-파일-다운로드" aria-label="Permalink to &quot;1. 설치 파일 다운로드&quot;">​</a></h2><p>Git 공식 홈페이지(<a href="https://git-scm.com" target="_blank" rel="noreferrer">https://git-scm.com</a>)에 접속해 Windows용 설치 파일을 내려받는다.</p><p><img src="'+i+'" alt="Git 공식 사이트 다운로드 화면"></p><hr><h2 id="_2-라이선스-정보-확인" tabindex="-1">2. 라이선스 정보 확인 <a class="header-anchor" href="#_2-라이선스-정보-확인" aria-label="Permalink to &quot;2. 라이선스 정보 확인&quot;">​</a></h2><p>설치 파일을 실행하면 Git Bash의 정보와 라이선스(GNU General Public License) 내용이 표시된다. <code>Next</code>를 누른다.</p><p><img src="'+r+'" alt="라이선스 정보 화면"></p><hr><h2 id="_3-설치-경로-지정" tabindex="-1">3. 설치 경로 지정 <a class="header-anchor" href="#_3-설치-경로-지정" aria-label="Permalink to &quot;3. 설치 경로 지정&quot;">​</a></h2><p>Git을 설치할 폴더를 선택한다. 특별한 이유가 없으면 기본 경로(<code>C:\\Program Files\\Git</code>)를 그대로 두고 <code>Next</code>를 누른다.</p><p><img src="'+c+'" alt="설치 경로 선택 화면"></p><hr><h2 id="_4-컴포넌트-선택" tabindex="-1">4. 컴포넌트 선택 <a class="header-anchor" href="#_4-컴포넌트-선택" aria-label="Permalink to &quot;4. 컴포넌트 선택&quot;">​</a></h2><p>설치할 구성 요소를 선택한다. 기본값으로 두고 <code>Next</code>를 눌러도 충분하다. (<code>Git Bash Here</code>, <code>Git GUI Here</code> 등이 기본 선택되어 있다.)</p><p><img src="'+l+'" alt="컴포넌트 선택 화면"></p><hr><h2 id="_5-시작-메뉴-폴더-선택" tabindex="-1">5. 시작 메뉴 폴더 선택 <a class="header-anchor" href="#_5-시작-메뉴-폴더-선택" aria-label="Permalink to &quot;5. 시작 메뉴 폴더 선택&quot;">​</a></h2><p>시작 메뉴에 폴더를 추가하고 싶지 않으면 <code>Don&#39;t create a Start Menu folder</code> 체크박스를 선택한다. 보통은 기본값으로 두고 <code>Next</code>를 누른다.</p><p><img src="'+d+'" alt="시작 메뉴 폴더 생성 화면"></p><hr><h2 id="_6-기본-에디터-설정" tabindex="-1">6. 기본 에디터 설정 <a class="header-anchor" href="#_6-기본-에디터-설정" aria-label="Permalink to &quot;6. 기본 에디터 설정&quot;">​</a></h2><p>Git이 사용할 기본 텍스트 에디터를 선택한다. VS Code처럼 평소 사용하는 에디터가 있다면 해당 에디터로 설정한다. 잘 모르겠으면 기본값(Vim)으로 두고 <code>Next</code>를 눌러도 된다.</p><p><img src="'+n+'" alt="기본 에디터 선택 화면"></p><hr><h2 id="_7-초기-브랜치-이름-설정" tabindex="-1">7. 초기 브랜치 이름 설정 <a class="header-anchor" href="#_7-초기-브랜치-이름-설정" aria-label="Permalink to &quot;7. 초기 브랜치 이름 설정&quot;">​</a></h2><p>새 저장소를 만들 때 사용할 초기 브랜치 이름을 정한다. 기본값(<code>Let Git decide</code>)으로 두고 <code>Next</code>를 누르면 된다.</p><p><img src="'+h+'" alt="초기 브랜치 이름 설정 화면"></p><hr><h2 id="_8-path-환경-설정" tabindex="-1">8. PATH 환경 설정 <a class="header-anchor" href="#_8-path-환경-설정" aria-label="Permalink to &quot;8. PATH 환경 설정&quot;">​</a></h2><p>명령행에서 Git을 어떻게 사용할지 선택한다. 권장 옵션인 <code>Git from the command line and also from 3rd-party software</code>가 기본 선택되어 있다. 그대로 두고 <code>Next</code>를 누른다.</p><p><img src="'+p+'" alt="PATH 환경 설정 화면"></p><hr><h2 id="_9-https-전송-방식-선택" tabindex="-1">9. HTTPS 전송 방식 선택 <a class="header-anchor" href="#_9-https-전송-방식-선택" aria-label="Permalink to &quot;9. HTTPS 전송 방식 선택&quot;">​</a></h2><p>HTTPS 연결에 사용할 라이브러리를 선택한다.</p><ul><li><strong>Use the OpenSSL library</strong>: OpenSSL 라이브러리를 사용하고 <code>ca-bundle.crt</code> 파일로 인증서 유효성을 검사한다. (기본값)</li><li><strong>Use the native Windows Secure Channel library</strong>: Windows 인증서 저장소를 사용해 인증서 유효성을 검사한다.</li></ul><p>기본값으로 두고 <code>Next</code>를 누른다.</p><p><img src="'+m+'" alt="HTTPS 보안 라이브러리 선택 화면"></p><hr><h2 id="_10-줄-끝-line-ending-변환-방식" tabindex="-1">10. 줄 끝(Line Ending) 변환 방식 <a class="header-anchor" href="#_10-줄-끝-line-ending-변환-방식" aria-label="Permalink to &quot;10. 줄 끝(Line Ending) 변환 방식&quot;">​</a></h2><p>텍스트 파일의 줄 끝 문자를 어떻게 변환할지 선택한다. 기본값으로 두어도 무관하다.</p><p><img src="'+g+'" alt="줄 끝 변환 방식 선택 화면"></p><hr><h2 id="_11-터미널-에뮬레이터-선택" tabindex="-1">11. 터미널 에뮬레이터 선택 <a class="header-anchor" href="#_11-터미널-에뮬레이터-선택" aria-label="Permalink to &quot;11. 터미널 에뮬레이터 선택&quot;">​</a></h2><p>Git Bash에서 사용할 터미널 에뮬레이터를 선택한다. 기본값(<code>Use MinTTY</code>)으로 두어도 무관하다.</p><p><img src="'+_+'" alt="터미널 에뮬레이터 선택 화면"></p><hr><h2 id="_12-git-pull-기본-동작-선택" tabindex="-1">12. <code>git pull</code> 기본 동작 선택 <a class="header-anchor" href="#_12-git-pull-기본-동작-선택" aria-label="Permalink to &quot;12. `git pull` 기본 동작 선택&quot;">​</a></h2><p><code>git pull</code> 실행 시 기본 동작을 선택한다. 기본값(<code>Default (fast-forward or merge)</code>)으로 두고 <code>Next</code>를 누른다.</p><p><img src="'+u+'" alt="git pull 기본 동작 설정 화면"></p><hr><h2 id="_13-자격-증명-관리자-credential-helper" tabindex="-1">13. 자격 증명 관리자(Credential Helper) <a class="header-anchor" href="#_13-자격-증명-관리자-credential-helper" aria-label="Permalink to &quot;13. 자격 증명 관리자(Credential Helper)&quot;">​</a></h2><p>자격 증명 저장 방식을 선택한다. 기본값(<code>Git Credential Manager Core</code>)으로 두고 <code>Next</code>를 누른다.</p><p><img src="'+b+'" alt="자격 증명 관리자 설정 화면"></p><hr><h2 id="_14-추가-옵션" tabindex="-1">14. 추가 옵션 <a class="header-anchor" href="#_14-추가-옵션" aria-label="Permalink to &quot;14. 추가 옵션&quot;">​</a></h2><p>추가 옵션을 선택한다.</p><ul><li><strong>Enable file system caching</strong>: 성능 향상을 위해 파일 시스템 데이터를 메모리에 캐시한다. (기본 선택)</li><li><strong>Enable symbolic links</strong>: 심볼릭 링크를 활성화한다. (기존 저장소는 영향을 받지 않음)</li></ul><p>기본값으로 두고 <code>Next</code>를 누른다.</p><p><img src="'+k+'" alt="추가 옵션 설정 화면"></p><hr><h2 id="_15-실험적-옵션" tabindex="-1">15. 실험적 옵션 <a class="header-anchor" href="#_15-실험적-옵션" aria-label="Permalink to &quot;15. 실험적 옵션&quot;">​</a></h2><p>실험적 기능 옵션이다. 그대로 두고 <code>Install</code>을 눌러 설치를 시작한다.</p><p><img src="'+f+'" alt="실험적 기능 옵션 화면"></p><hr><h2 id="_16-설치-진행" tabindex="-1">16. 설치 진행 <a class="header-anchor" href="#_16-설치-진행" aria-label="Permalink to &quot;16. 설치 진행&quot;">​</a></h2><p>설치가 진행된다. 잠시 기다린다.</p><p><img src="'+q+'" alt="설치 진행 화면"></p><hr><h2 id="_17-설치-완료" tabindex="-1">17. 설치 완료 <a class="header-anchor" href="#_17-설치-완료" aria-label="Permalink to &quot;17. 설치 완료&quot;">​</a></h2><p>설치가 끝나면 완료 화면이 나타난다. <code>Finish</code>를 눌러 마법사를 종료한다.</p><p><img src="'+x+'" alt="설치 완료 화면"></p><hr><h2 id="_18-설치-확인" tabindex="-1">18. 설치 확인 <a class="header-anchor" href="#_18-설치-확인" aria-label="Permalink to &quot;18. 설치 확인&quot;">​</a></h2><p>시작 메뉴에서 <code>Git Bash</code>가 보이면 정상이다. Git Bash 터미널을 열고 아래 명령을 실행해 버전이 출력되는지 확인한다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>버전 번호가 보이면 Git Bash 설치가 완료된 것이다.</p><blockquote><p>Antigravity IDE를 사용한다면, 내장 터미널의 <code>+</code> 또는 아래 화살표 메뉴에서 <code>Git Bash</code>를 선택해 터미널을 Git Bash로 바꿔서 사용한다.</p></blockquote><hr><p>← <a href="./../user-guide.html">사용자 가이드 홈으로</a> · 다음: <a href="./nodejs-install.html">Node.js 설치 가이드 →</a></p>',84)])])}const v=a(P,[["render",G]]);export{y as __pageData,v as default};
